delete from public.maintenance_templates;
select is((select count(*) from public.maintenance_templates),3::bigint,'RLS prevents direct deletion even with grants on maintenance_templates');
select throws_ok($$insert into public.maintenance_templates select * from public.maintenance_templates limit 1$$, '42501', null, 'RLS denies direct inserts on maintenance_templates');
update public.maintenance_assignments set name='tampered';
